use std::error::Error;

use infra_http::HttpContract;
// template:begin authn:service-api-authn-imports
use utoipa::Modify;
use utoipa::openapi::security::{Http, HttpAuthScheme, SecurityScheme};
// template:end authn:service-api-authn-imports
use utoipa::OpenApi;
use utoipa::openapi::OpenApi as Document;

use crate::AppState;

const GENERATED_HEADER: &str =
    "# Generated by `just openapi-generate` from the Rust contract; do not edit by hand.";

/// Document identity. `version` and `license` follow this crate's Cargo
/// metadata; the title names the service the way the repository does.
#[derive(OpenApi)]
#[openapi(
    info(
        title = "rust-service-template-rest",
        description = "HTTP contract served by the `service` binary: platform probes and feature operations, with RFC 9457 problem responses from one closed catalog. An unknown path returns a 404 Problem. An unsupported method returns a 405 Problem with Allow. The HTTP listener can reject oversized request headers with 431 before routing."
    ),
    servers((url = "/", description = "current service origin")),
    tags(
        (name = "system", description = "Operational endpoints for liveness and readiness."),
        // template:begin inbound-webhooks:service-api-webhooks-tag
        (name = "webhooks", description = "Authenticated inbound webhook admission.")
        // template:end inbound-webhooks:service-api-webhooks-tag
    ),
    // template:begin authn:service-api-authn-document-security
    modifiers(&BearerAuth),
    security(("bearerAuth" = []))
    // template:end authn:service-api-authn-document-security
)]
struct ApiDoc;

// template:begin authn:service-api-authn-security-scheme
struct BearerAuth;

impl Modify for BearerAuth {
    fn modify(&self, document: &mut Document) {
        document
            .components
            .get_or_insert_default()
            .add_security_scheme(
                "bearerAuth",
                SecurityScheme::Http(Http::new(HttpAuthScheme::Bearer)),
            );
    }
}
// template:end authn:service-api-authn-security-scheme

#[derive(Debug, thiserror::Error)]
pub enum ContractError {
    #[error(transparent)]
    Finalization(#[from] infra_http::FinalizeError),
    #[error("render the OpenAPI document as YAML: {0}")]
    Yaml(#[source] Box<dyn Error + Send + Sync>),
}

pub fn contract() -> Result<HttpContract<AppState>, ContractError> {
    let contract = HttpContract::application(ApiDoc::openapi())?;
    // template:begin inbound-webhooks:service-api-webhooks-router
    let contract = contract.merge(infra_webhooks::inbound::route::router()?)?;
    // template:end inbound-webhooks:service-api-webhooks-router
    // template:begin outbound-auth:service-api-outbound-test-route
    #[cfg(test)]
    let contract = contract.merge(crate::bootstrap::outbound_tests::route()?)?;
    // template:end outbound-auth:service-api-outbound-test-route
    Ok(contract.with_probes("/")?)
}

pub fn document() -> Result<Document, ContractError> {
    Ok(contract()?.into_openapi()?)
}

pub fn render() -> Result<String, ContractError> {
    let yaml = document()?
        .to_yaml()
        .map_err(|err| ContractError::Yaml(Box::new(err)))?;
    Ok(format!("{GENERATED_HEADER}\n{}\n", yaml.trim_end()))
}

// template:begin http-idempotency:service-api-idempotent-test-route
#[cfg(test)]
mod idempotency_tests {
    use std::convert::Infallible;

    use infra_http::idempotency::{CreatedText, FreshCommand, Rollback, Tx};

    use super::*;

    #[utoipa::path(
        post,
        path = "/_test/idempotent",
        tag = "system",
        operation_id = "testIdempotent",
        summary = "Test-only idempotent composition seam",
        security(("bearerAuth" = [])),
        extensions(
            ("x-security-decision" = json!({
                "exposure": "protected",
                "rationale": "test-only route proving the production idempotency composition seam"
            }))
        ),
        responses(infra_http::authn::ProtectedOperationProblemResponses)
    )]
    async fn idempotent() -> Result<Create, infra_http::Problem> {
        Ok(Create)
    }

    struct Create;

    impl FreshCommand for Create {
        type Success = CreatedText;
        type Terminal = Infallible;

        fn execute(
            self,
            _: &mut Tx<'_>,
        ) -> impl Future<Output = Result<Self::Success, Rollback<Self::Terminal>>> + Send {
            std::future::ready(Ok(CreatedText::new("created")))
        }
    }

    fn test_route() -> HttpContract<AppState> {
        infra_http::idempotent_route!(idempotent, docs = "https://docs.example/test#retry")
            .expect("test route composes")
    }

    #[test]
    fn test_only_idempotent_route_generates_the_served_contract() {
        let contract = contract().unwrap().merge(test_route()).unwrap();
        assert_eq!(contract.idempotent_operations(), 1);
        let document = serde_json::to_value(contract.into_openapi().unwrap()).unwrap();
        let operation = &document["paths"]["/_test/idempotent"]["post"];
        assert!(operation.get("x-idempotent").is_none());
        let parameters = operation["parameters"].as_array().unwrap();
        let key = parameters
            .iter()
            .find(|parameter| parameter["name"] == "Idempotency-Key")
            .expect("composition adds the key parameter");
        assert_eq!(key["in"], "header");
        assert_eq!(key["required"], true);
        assert_eq!(key["schema"]["type"], "string");
        assert!(key["schema"].get("maxLength").is_none());
        assert!(key["schema"].get("pattern").is_none());
        for (status, component) in [
            ("401", "AuthenticationUnauthorized"),
            ("403", "AuthenticationForbidden"),
            ("408", "RequestTimeout"),
            ("409", "IdempotencyRequestInProgress"),
            ("413", "RequestEntityTooLarge"),
            ("422", "IdempotencyKeyMismatch"),
            ("500", "InternalServerError"),
        ] {
            assert_eq!(
                operation["responses"][status]["$ref"],
                format!("#/components/responses/{component}")
            );
        }
        for (status, header) in [("400", "WWW-Authenticate"), ("503", "Retry-After")] {
            let response = &operation["responses"][status];
            assert!(
                response["content"]
                    .get("application/problem+json")
                    .is_some()
            );
            assert!(response["headers"].get(header).is_some());
        }
        assert_eq!(operation["responses"]["201"]["description"], "created");
        assert_eq!(
            operation["responses"]["201"]["content"]["text/plain"]["schema"]["type"],
            "string"
        );
        assert_eq!(
            operation["responses"]["201"]["headers"]["Idempotent-Replayed"]["schema"],
            serde_json::json!({ "type": "string", "enum": ["true"] })
        );
    }

    #[test]
    fn a_document_only_operation_cannot_shadow_a_nested_idempotent_handler() {
        let stale = serde_json::from_value(serde_json::json!({
            "openapi": "3.1.0", "info": {"title": "stale", "version": "1"},
            "paths": {"/api/_test/idempotent": {"post": {
                "security": [], "responses": {"200": {"description": "stale public response"}}
            }}}
        }))
        .unwrap();
        assert_eq!(
            HttpContract::<AppState>::application(stale)
                .unwrap_err()
                .to_string(),
            "application metadata must contain no registered paths"
        );
    }

    #[test]
    fn constructing_an_unmounted_route_leaves_the_service_inactive() {
        let service = contract().unwrap();
        drop(test_route());
        assert_eq!(service.idempotent_operations(), 0);
    }
}
// template:end http-idempotency:service-api-idempotent-test-route
